numbers = []
while True:
    line = input("Number (done to stop): ").strip()
    if line.lower() == "done":
        break
    numbers.append(float(line))

if not numbers:
    print("no numbers")
else:
    print(f"count {len(numbers)}")
    print(f"sum {sum(numbers):g}")
    print(f"average {sum(numbers) / len(numbers):.2f}")
    print(f"largest {max(numbers):g}")
